import datetime
import json


async def main(args: Args) -> Output:
    p = args.params or {}
    raw = p.get('llm_stages_json')
    try:
        now = int(p.get('in_now_ts') or 0)
    except Exception:
        now = 0
    if now <= 0:
        now = int(datetime.datetime.now().timestamp())

    data = []
    if isinstance(raw, list):
        data = raw
    elif isinstance(raw, str) and raw.strip():
        try:
            data = json.loads(raw)
        except Exception:
            data = []
    if not isinstance(data, list):
        data = []

    stages = []
    for i, s in enumerate(data):
        if not isinstance(s, dict):
            continue
        try:
            off_s = int(float(s.get('offset_start_days') or 0))
        except Exception:
            off_s = 0
        try:
            off_e = int(float(s.get('offset_end_days') or off_s))
        except Exception:
            off_e = off_s
        if off_e < off_s:
            off_e = off_s
        start_ts = now + off_s * 86400
        end_ts = now + off_e * 86400
        stages.append({
            'stage_index': i + 1,
            'stage_name': str(s.get('stage') or ''),
            'start_ts': start_ts,
            'end_ts': end_ts,
            'start_label': datetime.datetime.fromtimestamp(start_ts).strftime('%Y-%m-%d'),
            'end_label': datetime.datetime.fromtimestamp(end_ts).strftime('%Y-%m-%d'),
            'deliverable': str(s.get('deliverable') or ''),
            'action': str(s.get('action') or ''),
        })

    lines = []
    for s in stages:
        lines.append('%d. %s（%s ~ %s）\n   要做的：%s\n   阶段产出：%s' % (
            s['stage_index'], s['stage_name'], s['start_label'], s['end_label'],
            s['action'], s['deliverable']))

    days_left = 0
    if stages:
        days_left = int((int(stages[0]['end_ts']) - now) / 86400)

    if stages:
        summary = ('你的阶段性生涯路径（共 %d 个阶段）：\n%s\n\n'
                   '当前第一阶段还剩 %d 天，建议本周先完成它的第一条动作。') % (
            len(stages), '\n'.join(lines), days_left)
    else:
        summary = ''

    ret: Output = {
        'v_summary': summary,
        'v_stages': stages,
        'v_stage_count': len(stages),
        'v_days_left': days_left,
    }
    return ret

async def main(args: Args) -> Output:
    p = args.params or {}
    tip = str(p.get('v_tip_text') or '信息还不足，请补齐档案后重试。')
    ret: Output = {
        'v_summary': tip,
        'v_stages': [],
        'v_stage_count': 0,
        'v_days_left': 0,
    }
    return ret
